class Solution {
public:
    int countLatticePoints(vector<vector<int>>& circles) {
        vector<vector<bool>> seen(201, vector<bool>(201, false));
        int ans = 0;
        for (const auto& c : circles) {
            int cx = c[0], cy = c[1], r = c[2];
            for (int x = cx - r; x <= cx + r; x++) {
                for (int y = cy - r; y <= cy + r; y++) {
                    if (!seen[x][y] && (x - cx) * (x - cx) + (y - cy) * (y - cy) <= r * r) {
                        seen[x][y] = true;
                        ans++;
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int countLatticePoints(int[][] circles) {
        boolean[][] seen = new boolean[201][201];
        int ans = 0;
        for (int[] c : circles) {
            int cx = c[0], cy = c[1], r = c[2];
            for (int x = cx - r; x <= cx + r; x++) {
                for (int y = cy - r; y <= cy + r; y++) {
                    if (!seen[x][y] && (x - cx) * (x - cx) + (y - cy) * (y - cy) <= r * r) {
                        seen[x][y] = true;
                        ans++;
                    }
                }
            }
        }
        return ans;
    }
}

